  return strings.Join(fields,", ")
 }
 params:=tuple(sig.Params(),sig.Variadic())
 returns:=tuple(sig.Results(),false)
 if !changed{return result}
 prefix:=""
 if list:=sig.TypeParams();list!=nil&&list.Len()>0{
  parts:=[]string{}
  for i:=0;i<list.Len();i++{p:=list.At(i);parts=append(parts,p.Obj().Name()+" "+types.TypeString(p.Constraint(),nil))}
