func(a *aliasInfo)setSignatureAliases(ft *ast.FuncType,sig *types.Signature){
 set:=func(fields *ast.FieldList,vars *types.Tuple){
  if fields==nil{return};i:=0
  for _,f:=range fields.List{n:=len(f.Names);if n==0{n=1};al:=a.typeName(f.Type);for j:=0;j<n;j++{if al!=nil&&i<vars.Len(){a.objects[vars.At(i)]=al};i++}}
 }
 set(ft.Params,sig.Params());set(ft.Results,sig.Results())
}

func(a *aliasInfo)objectString(obj types.Object)string{
 result:=obj.String()
 sig,ok:=obj.Type().(*types.Signature);if !ok{return result}
 changed:=false
 tuple:=func(t *types.Tuple,variadic bool)string{
  fields:=[]string{}
  for i:=0;i<t.Len();i++{
   v:=t.At(i);typ:=v.Type();s:=types.TypeString(typ,nil)
   if al:=a.objects[v];al!=nil{s=al.full;changed=true}
   if variadic&&i==t.Len()-1{if slice,ok:=typ.(*types.Slice);ok{s="..."+types.TypeString(slice.Elem(),nil)}}
   if v.Name()!=""{s=v.Name()+" "+s};fields=append(fields,s)
  }
  return strings.Join(fields,", ")
 }
 params:=tuple(sig.Params(),sig.Variadic())
 returns:=tuple(sig.Results(),false)
 if !changed{return result}
 prefix:=""
 if list:=sig.TypeParams();list!=nil&&list.Len()>0{
  parts:=[]string{}
  for i:=0;i<list.Len();i++{p:=list.At(i);parts=append(parts,p.Obj().Name()+" "+types.TypeString(p.Constraint(),nil))}
  prefix="["+strings.Join(parts,", ")+"]"
 }
 tail:=prefix+"("+params+")"
 if sig.Results().Len()>0{
  if sig.Results().Len()==1&&sig.Results().At(0).Name()==""{tail+=" "+returns}else{tail+=" ("+returns+")"}
 }
 plain:=strings.TrimPrefix(types.TypeString(sig,nil),"func")
 if strings.HasSuffix(result,plain){return strings.TrimSuffix(result,plain)+tail}
 return result
}
EOF
